def table(headers,rows): return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
slides=[]
def add(title,body,note,ref): slides.append((title,body,note,ref))
add('COT何时能改善站点GHI估计？','<p class="hero">基础同期模型有收益；<br>更强基线与预报链路中的收益还不稳定。</p><p>今天只讨论三个问题：<b>收益出现在哪里？何时失效？怎样传到预报？</b></p><p class="small">湖南两站 + 湖北三站，各区域独立训练；阶段性验证结果 · 2026-10-16</p>','开场不介绍卫星、COT定义或神经网络背景。我们的目标是验证物理表示对GHI的实际价值，不把外推创新作为本篇贡献。同期反演与提前预报分开回答。','E1–E8')
add('问题1：同样的云图，显式COT能否帮助GHI估计？','<div class="flow">真实AGRI → 冻结反演器R → 局地COT<br>AGRI + 太阳几何 [ + COT ] → 同期15分钟GHI</div>'+table(['区域 / 独立训练','无COT','加COT','RMSE降幅'],[['湖南两站 / 三种子','123.980','120.240','3.02%'],['湖北三站 / 三种子','74.361','71.428','约3.94%']])+'<p>两省基础头都显示增益；湖北容量匹配对照为73.894，加COT仍较低。</p><p class="small">单位W/m²；站点、种子等权。ΔRMSE日期块95%区间：湖南[−6.180,−1.597]；湖北[−5.070,−0.939]。区域之间不横向比绝对精度。</p>','这是同期估计，不能称未来预报。COT来自同一AGRI，经CPP监督的R变成物理表示，不是新增独立观测。湖南4479个验证行；湖北三站验证856/784/816行。各区域内样本、标签配对。湖北27组已完成且报告记录checkpoint重载及保存预测复算。区间未消除验证选模影响。','E1、E3')
add('收益是否集中在特定云厚度？',table(['CPP参考分层','无COT → 加COT RMSE','降幅','ΔRMSE日期块95%区间'],[['近零 [0,0.1)','159.165 → 156.812','1.48%','[−6.238,+1.157]'],['薄云 [0.1,5)','165.869 → 163.045','1.70%','[−6.814,+1.268]'],['中等 [5,30)','122.509 → 120.430','1.70%','[−7.179,+3.030]'],['厚云 [30,100]','74.929 → 58.105','22.45%','[−21.862,−12.359]']])+'<p class="take">最清楚的改善是：厚云参考样本中，无COT头的高估被减轻。</p><p class="small">湖南基础同期头；有CPP支持的1284行。厚云173行、25天；其他三层区间跨零。CPP为检索参考。</p>','22.45%只属于这个厚云子组，不能替代总体3.02%。厚云两站bias分别由+14.460到+1.648、+48.356到+19.432 W/m²，支持减少高估这一描述。不是证明云越厚收益一定越大，也不是COT反演误差下降22%。同一CPP覆盖子集，不代表全年天气分布。','E2')
add('问题2：收益取决于原始AGRI利用得是否充分？',table(['配对实验（各自独立合同）','无显式COT','加显式COT','加COT的差值'],[['湖南基础头','123.980','120.240','−3.740'],['统一输入的AGRI残差头','111.277','113.419','+2.142'],['三帧局地头 / 修正几何R','108.236','107.784','−0.452']])+'<p>残差头差值区间[−0.688,+4.745]；三帧头[−2.294,+1.101]。</p><p class="take">显式COT的额外价值随输入和头部设计变化，不能把基础头的3%当作普遍增益。</p><p class="small">各行内部可配对；不把跨行变化归因于某一个因素。三帧头另有4263条验证行。</p>','不需要证明COT拥有无法替代的信息才有应用价值，但需要强基线。R隐特征对照119.807与显式COT120.240差异区间也跨零：提示物理监督形成的表示有价值，尚未区分显式标量与隐表示优势。三帧相对单帧同时改变合同，不能说历史完全解释了之前收益。','E1、E4、E5')
add('真实失败例：COT接近参考，GHI仍被严重低估',img('sili_failure_top.png')+'<p><b>四里 2025-08-22 12:15 BJT</b>：实测1191.3，无COT 751.3，加COT 699.2 W/m²。</p><p>三帧中心R-COT：3.32 / 4.59 / 5.64；CPP参考：3.63 / 4.36 / 5.16。</p><p class="small">真实AGRI C03/C02/C01假彩色；青框为3×3 GHI输入。同期病例，不是预报曲线。上半图原样裁出，完整配对图见assets。</p>','这不是单纯把厚云反演薄了。COT估计接近CPP并不意味着站点15分钟GHI必然正确。需要检查局地光学厚度如何与太阳方向、云位置、时间支持共同决定透射。不能凭此宣称已证明云边增强或云影错位。病例按失败结果选出，只用于解释，不估计发生频率。','E6')
add('从失败例能提出什么可检验问题？','<div class="cards"><div><h3>光学厚度 → 区间GHI的映射</h3><p>254条三种子共同退化样本中，90条中心COT&lt;0.1；不能只归因于厚云压低GHI。</p></div><div><h3>空间与时间是否对应站点受光？</h3><p>约3分钟扫描偏移、太阳方向和云高都是候选因素；目前尚无统一的物理归因。</p></div></div><p class="take">首先判断“COT估错”还是“同样COT对应的GHI关系没学好”，再决定是否改模型。</p><p class="small">已核对标签窗口与输入索引；不是发现了普遍UTC/15分钟错位。已有残差实验，不重复泛泛提出“加残差”。</p>','两个独立训练头的AC−A不能直接解释为COT衰减量。冻结AC内的参考替换诊断显示，在严重失败组，真实COT相对训练均值反而提高输出11.9 W/m²，但AC仍低于A；表明头本身映射变化也参与。训练均值替换不是晴空，更不是重训无COT模型。后续只在来源齐全的案例检验扫描时段/视差/云影，不造云高。','E6；docs/HIGH_GHI_UNDERESTIMATION.md')
add('问题3：同期收益是否已传到0–4小时预报？',table(['四里旧划分预报pilot / 三种子','全16时效RMSE','相对无COT'],[['无COT','158.76','—'],['历史COT输运','167.22','退化5.33%'],['历史COT混合预测','166.79','退化5.06%']])+'<p>+1小时有小幅点改善；+2～4小时普遍退化。</p><p class="take">当前不能说“反演改善，同时预报也已改善”。</p><p class="small">选模与评分初始化日期分开；仍是旧划分单站探索，不是新月度双站最终结果。两个总体差值区间均在零以上。</p>','之前选模后约1%的改善来自同一验证日期的事后checkpoint检查，区间跨零；本页是修正选模流程后结果，不隐瞒。不能把负结果直接归罪外推算法：未来COT误差和GHI头适配都可能参与。混合方案还使用SimVP辅助，不是纯COT外推。node22 A800属于浙师大学院服务器，汇报无需讲机器。','E7')
add('下一步只回答两个实际问题','<ol><li><b>同期增益能否在明确的输入合同下站得住？</b><br>保留两区域基础对照，报告强AGRI/三帧对照；补足高GHI低估与厚云高估的配对病例解释。</li><li><b>预报损失主要来自COT预测，还是GHI映射？</b><br>在同一预报样本、同一GHI头下分开比较预测COT与真实未来图反演COT；后者只作离线诊断，并与可部署结果分开。</li></ol><p class="take">本篇重点：物理表示的条件性收益；外推作为应用检验，不强行写成已成功。</p><p>请老师重点判断：是否以“同期估计及厚云情景”为主贡献，预报作为尚待完成的扩展验证？</p>','已做过的固定头替换和oracle诊断先复用，不再重复跑相同实验。湖北同期已完成，正式预报GHI配对尚未完成。下一步需先归并同合同证据，只有现有证据无法回答时做单因素实验。若最终预报仍无收益，诚实报告，不无限换外推网络。IFS后置不作为今晚未兑现承诺。','E1–E7')
add('备查：历史COT外推与Cloud-FNO的量级',img('cloud_fno.png')+'<p class="small">本项目旧验证窗口与论文数据域、卫星、参考产品、分辨率和评价支持不同。图只能作量级参照，不能排名或证明“已达同等水平”。</p>','未来1/2/3/4h物理COT RMSE，论文图读数约6.75/8.09/8.93/9.61；本项目输运局地场约7.42/9.80/11.18/11.99。站点和区域口径必须分开。COT RMSE数值接近并不能保证GHI收益，位置、极值、到达时间误差仍需看。','E8')
add('备查：预报分时效结果',img('forecast.png')+'<p class="small">保存预测FP64复算；仅对应旧四里attempt3。不能与同期RMSE或其他日期划分直接拼接成一条改进曲线。</p>','测试未打开。日期块区间是当前验证数据条件下的统计不确定性，不是独立测试保证；评分日期也曾进入此前诊断，因此只称内部留出评分。','E7')
css='''*{box-sizing:border-box}body{margin:0;background:#edf2f6;color:#142a3b;font-family:"Microsoft YaHei",Arial,sans-serif}section{display:none;max-width:1440px;min-height:100vh;margin:auto;background:white;padding:36px 65px 72px}section.active{display:block}h1{font-size:34px;margin:8px 0 25px;letter-spacing:-.5px}p,li{font-size:23px;line-height:1.6}li{margin:20px 0}.hero{font-size:41px;font-weight:700;color:#006c70;margin:55px 0}.small{font-size:16px;color:#526578}table{border-collapse:collapse;width:100%;font-size:21px;margin:25px 0}th,td{text-align:left;padding:17px;border-bottom:1px solid #dce5ec}th{background:#edf6f5}tr:last-child td{color:#006d6e;font-weight:600}.take{border-left:6px solid #009b8c;padding:12px 20px;background:#eef8f6;font-weight:600}.flow{padding:20px;background:#edf6f5;font-size:24px;line-height:1.8}.cards{display:flex;gap:25px}.cards>div{flex:1;padding:20px;background:#f1f5f8}h3{font-size:23px}img{display:block;max-width:100%;max-height:61vh;object-fit:contain;margin:8px auto}aside{display:none;padding:18px;background:#fff6d8;font-size:17px;line-height:1.7}.show-notes aside{display:block}footer{font-size:14px;color:#71818e;margin-top:22px}nav{position:fixed;bottom:0;width:100%;background:#112b3d;color:white;padding:12px 25px;display:flex;gap:20px;align-items:center}button{background:#24536a;color:white;border:0;padding:8px 20px;cursor:pointer;font-size:16px}#count{margin-right:auto}@media print{section{display:block!important;min-height:0;break-after:page;padding:25px}nav{display:none}aside{display:none!important}img{max-height:55vh}}'''
parts=[]
for i,(t,b,n,r) in enumerate(slides,1): parts.append(f'<section class="{"active" if i==1 else ""}"><div class="small">COT与站点GHI · 组会 · {i:02d}</div><h1>{t}</h1>{b}<aside><b>讲述提示：</b>{n}</aside><footer>依据：{r} ｜ 阶段性validation证据，非独立test结论 ｜ 详细来源见EVIDENCE_INDEX.md</footer></section>')
js='''let k=0;const s=[...document.querySelectorAll('section')];function go(d){k=Math.max(0,Math.min(s.length-1,k+d));s.forEach((x,i)=>x.classList.toggle('active',i===k));document.querySelector('#count').textContent=(k+1)+' / '+s.length;window.scrollTo(0,0)}function notes(){document.body.classList.toggle('show-notes')}document.onkeydown=e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();go(1)}if(['ArrowLeft','PageUp'].includes(e.key))go(-1);if(e.key.toLowerCase()==='n')notes();if(e.key.toLowerCase()==='f')document.documentElement.requestFullscreen?.()};go(0);'''
(O/'group_meeting.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>COT组会 · 2026-10-16</title><style>'+css+'</style><body>'+''.join(parts)+'<nav><span id="count"></span><button onclick="go(-1)">上一页</button><button onclick="go(1)">下一页</button><button onclick="notes()">讲稿 N</button><span>← → 翻页 · F 全屏</span></nav><script>'+js+'</script></body></html>',encoding='utf-8')
md=['# COT组会讲述提纲｜2026-10-16','建议主讲8页、12–15分钟；最后2页备查。打开同目录group_meeting.html，方向键翻页，N显示讲稿，F全屏。','## 开场可以直接这样说','我们先把同期反演与提前预报分开。基础同期头在湖南、湖北都看到约3%–4%的验证改善，湖南厚云参考样本改善更明显。但增强AGRI基线后，额外COT收益并不稳定；已有历史COT预报pilot还出现退化。所以今天重点不是证明COT普遍有效，而是定位它在哪些输入条件、哪些受光情景下真正有用。']
for i,(t,b,n,r) in enumerate(slides,1): md += [f'## 第{i}页｜{t}',n,f'支撑材料：{r}。']
md += ['## 老师可能追问','- **COT不是从同一云图得来的吗？** 是。它不是独立新观测，而是CPP监督的物理表示；实证问题是能否帮助有限数据和指定头部更好地利用AGRI。','- **厚云22.45%能作为全文结论吗？** 只能作为湖南基础头、173个有参考支持样本的分层发现；总体为3.02%，其他层区间跨零。','- **COT准了，为什么GHI还差？** COT场准确并不自动保证太阳方向上的站点区间透射关系准确。实际病例显示R接近CPP仍低估GHI，但云影/视差/扫描时间尚未分别确证。','- **是不是只是多参数？** 湖北AC优于容量匹配AP；湖南R隐特征也有相似表现。支持物理监督表示的实用性，尚不证明显式COT独占优势。','- **是不是外推造成的？** 是候选解释，不能直接盖章。需要同样本固定头分离来源误差和映射适配；复用已做诊断，不反复重做。','- **还缺什么才能成文？** 冻结最终同期输入合同和主基线；归并两区域及条件分层证据；完成正式预报配对或明确负结果边界；最后按既定协议独立测试。方法可先写，结论不能预填。','## 今晚不放的内容','不放太阳能背景、COT定义、网络逐层教学、服务器排队、修复日志、过往所有候选路线。Cloud-FNO只备查，不用跨数据集数字作为方法胜负。不要重复“有COT必然更好”或把所有失败归因于外推。','## 范围与材料说明','本次只整理已有报告和真实图，不启动训练，不读取test，不修改论文。湖北结果来自当前保存的进展审计报告；本次未重新下载远端逐样本预测。原图仅作上半图裁切以便投屏，未改像元与曲线；原图保留在assets。所有数值为各自实验合同下结果，不能跨合同混算。']
(O/'组会讲述提纲.md').write_text('\n\n'.join(md),encoding='utf-8')
idx=['# 支撑材料索引','材料截至本次读取的2026-10-16记录；不是远端作业实时监控。','主展示只用已有验证结果。原始数据、checkpoint、复算入口详见各源报告。']
for key,p in sources.items(): idx += [f'## {key}',f'[{p}]({(R/p).as_posix()})',f'SHA256: `{hashlib.sha256((R/p).read_bytes()).hexdigest()}`']
for p in A.iterdir(): idx += [f'- 图：{p.name}；SHA256 `{hashlib.sha256(p.read_bytes()).hexdigest()}`']
(O/'EVIDENCE_INDEX.md').write_text('\n\n'.join(idx),encoding='utf-8')
